import json
import boto3
import hashlib
import time
from flask import Flask, request, jsonify, session

app = Flask(__name__)
app.secret_key = 'production-secret-key-2024'

# Session store backed by DynamoDB
dynamodb = boto3.resource('dynamodb')
session_table = dynamodb.Table('workflow-sessions')
sfn_client = boto3.client('stepfunctions')

STATE_MACHINE_ARN = 'arn:aws:states:us-east-1:123456789012:stateMachine:PaymentWorkflow'

@app.route('/api/workflow/init', methods=['POST'])
def init_workflow():
    """Initialize a Step Functions workflow with session binding"""
    user_id = request.headers.get('X-User-Id')
    # Session ID can be provided by client for resumption
    session_id = request.args.get('session_id') or request.headers.get('X-Session-Id')

    if not session_id:
        session_id = hashlib.sha256(f"{user_id}{time.time()}".encode()).hexdigest()[:32]

    # VULNERABILITY: No validation that session_id belongs to requesting user
    # An attacker can fixate a known session_id and then hijack the workflow
    session_table.put_item(Item={
        'session_id': session_id,
        'user_id': user_id,
        'state': 'INITIALIZED',
        'created_at': int(time.time()),
        'workflow_data': {}
    })

    # Start Step Functions execution with session binding
    execution = sfn_client.start_execution(
        stateMachineArn=STATE_MACHINE_ARN,
        name=f"workflow-{session_id}",
        input=json.dumps({
            'session_id': session_id,
            'user_id': user_id,
            'payment_authorized': False
        })
    )

    return jsonify({
        'session_id': session_id,
        'execution_arn': execution['executionArn'],
        'status': 'initialized'
    })

@app.route('/api/workflow/authorize-payment', methods=['POST'])
def authorize_payment():
    """Authorize payment in the workflow - uses session_id for lookup"""
    session_id = request.args.get('session_id') or request.headers.get('X-Session-Id')

    if not session_id:
        return jsonify({'error': 'session_id required'}), 400

    # Retrieve session - NO CHECK that current user owns this session
    resp = session_table.get_item(Key={'session_id': session_id})
    item = resp.get('Item')

    if not item:
        return jsonify({'error': 'session not found'}), 404

    # Update workflow state - attacker with fixated session can authorize payments
    session_table.update_item(
        Key={'session_id': session_id},
        UpdateExpression='SET #s = :state, workflow_data.payment_authorized = :auth',
        ExpressionAttributeNames={'#s': 'state'},
        ExpressionAttributeValues={':state': 'PAYMENT_AUTHORIZED', ':auth': True}
    )

    # Send task success to Step Functions
    sfn_client.send_task_success(
        taskToken=item.get('task_token', ''),
        output=json.dumps({'payment_authorized': True, 'session_id': session_id})
    )

    return jsonify({'status': 'payment_authorized', 'session_id': session_id})

@app.route('/api/workflow/status', methods=['GET'])
def workflow_status():
    """Check workflow status by session"""
    session_id = request.args.get('session_id')
    resp = session_table.get_item(Key={'session_id': session_id})
    item = resp.get('Item')
    if not item:
        return jsonify({'error': 'not found'}), 404
    return jsonify({'session_id': session_id, 'state': item['state'], 'user_id': item['user_id']})

@app.route('/internal/workflow/callback', methods=['POST'])
def sfn_callback():
    """Internal callback from Step Functions task state"""
    data = request.json
    session_id = data.get('session_id')
    task_token = data.get('task_token')

    session_table.update_item(
        Key={'session_id': session_id},
        UpdateExpression='SET task_token = :token',
        ExpressionAttributeValues={':token': task_token}
    )
    return jsonify({'status': 'callback_registered'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
